#!/usr/bin/env bash
# BancoXYZ EFT S9 — cierre de DOCUMENTACION y PDF (idempotente).
# No ejecuta jobs, Maven, Docker, SQL ni comandos destructivos.
# No modifica CSV, Java, snapshots, bases de datos o volumenes.
set -Eeuo pipefail
if [[ -f "pom.xml" && -d "Semana 9" ]]; then
 ROOT="$(pwd -P)"
else
 HERE="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"
 ROOT="$(cd -- "$HERE/../.." && pwd -P)"
fi
[[ -f "$ROOT/pom.xml" && -d "$ROOT/Semana 9" ]] || { echo 'ERROR: ejecutar desde la raiz de bancoxyzbatch.' >&2; exit 2; }
python3 - "$ROOT" <<'PYTHON_S9'
import base64, gzip, os, re, subprocess, sys, tempfile
from pathlib import Path
root=Path(sys.argv[1])
changes={}

def replace_exact(s,old,new,description):
    if old in s: return s.replace(old,new)
    if new in s: return s
    raise RuntimeError('Archivo distinto a la version revisada; no se altero nada: '+description)

def section(s,start,end,content,description):
    p=s.find(start);q=s.find(end,p+len(start))
    if p==-1 or q==-1: raise RuntimeError('Seccion no encontrada: '+description)
    if start+content in s[p:q]: return s
    return s[:p]+start+content+'\n\n'+s[q:]

def md(name):
    f=root/name
    if not f.is_file(): raise RuntimeError('Falta documento: '+name)
    return f.read_text(encoding='utf-8')

def put(name,new): changes[name]=new
read=md('README.md')
ins=md('instrucciones.md')
des=md('despliegue.md')
pro=md('Propuesta_Tecnica.md')
# Repositorio basado en la URL ya documentada en despliegue.md (no se inventa).
m=re.search(r'https://github\.com/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+(?:\.git)?',des)
if not m: raise RuntimeError('No se encuentra URL GitHub en despliegue.md; no se puede agregar enlace al README.')
git_url=m.group(0).removesuffix('.git')
# Evitar afirmar que es un enlace accesible si no se puede comprobar publicamente.
read=replace_exact(read,
 'El servicio Batch se ejecuta de manera aislada sobre PostgreSQL.',
 'Spring Batch utiliza la base consolidada `bancoxyz` compartida por los servicios del stack.',
 'README: arquitectura en resumen')
read=replace_exact(read,'    BATCH["Spring Batch: 3 Jobs"] --> BDB["PostgreSQL Batch aislado"]',
 '    BATCH["Spring Batch: 3 Jobs"] --> DB','README: diagrama Batch')
read=replace_exact(read,'PostgreSQL Batch aislado\n\nCliente',
 'PostgreSQL 17: base bancoxyz\n\nCliente','README: flujo')
read=replace_exact(read,
 'La base Batch es independiente de la base usada por los microservicios.',
 'Los resultados derivados de Batch se almacenan en la misma base PostgreSQL `bancoxyz` utilizada por el backend y los microservicios.',
 'README: parrafo Batch')
read=replace_exact(read,
 '''El snapshot incluido, generado a partir de los CSV oficiales, contiene:

```text
Cuentas procesadas ............... 50
Estados de cuenta anuales ........ 20
Transacciones procesadas ......... 482
Resúmenes diarios ................ 265
```''',
 '''La validación real de PostgreSQL del 11 de octubre de 2026, ejecutada desde los **tres CSV de Semana 9** y sin utilizar el snapshot legacy, obtuvo:

```text
Cuentas con intereses ............ 50
Estados de cuenta anuales ........ 20
Transacciones procesadas ......... 474
Resúmenes diarios ................ 261
```

La segunda ejecución Batch (JobExecution 31, 32 y 33) mantuvo los conteos y el contenido de negocio de las cuatro tablas. Los SHA-256 de los CSV originales no cambiaron.''',
 'README: snapshot/count')
read=replace_exact(read,
 'El script valida CSV, Maven, Compose, los tres Jobs Batch, OAuth2, BFF, Kafka, listener, Resilience4j y un retiro controlado. La base de prueba Batch se llama `bancoxyz_batch_eft_aislado` y no elimina la base principal.',
 'El auditor de cierre `Semana 9/scripts/cierre_total_bancoxyz_s9.sh` valida CSV, reactor Maven, Compose, tablas y los tres Jobs sobre `bancoxyz`. Reejecuta Jobs para comprobar idempotencia y no elimina bases, volúmenes ni CSV. La validación BFF adicional requiere `--probar-bff` y el stack levantado.',
 'README: verificador')
read=replace_exact(read,
 "fish 'Semana 9/scripts/verificar_entrega_completa.fish'\n",
 "bash 'Semana 9/scripts/cierre_total_bancoxyz_s9.sh' --todo\n",
 'README: comando prueba')
read=replace_exact(read,
 "fish 'Semana 9/scripts/verificar_entrega_completa.fish' --ec2\n",
 "bash 'Semana 9/scripts/cierre_total_bancoxyz_s9.sh' --todo --probar-bff\n",
 'README: comando EC2')
read=replace_exact(read,
 '| PDF y video final | ⏳ se completarán con evidencia real |',
 '| PDF y video final | PDF técnico preparado (adaptación a plantilla AVA pendiente); MP4 pendiente |',
 'README: tabla entregables')
read=replace_exact(read,
 '4. construir el PDF final de Semana 9;',
 '4. adaptar el PDF técnico adjunto a la plantilla oficial del AVA y completar capturas faltantes;',
 'README: pendientes')
if git_url not in read:
 read=replace_exact(read, '## ✨ Resumen',
 '## ✨ Resumen\n\n**Repositorio GitHub:** ['+git_url+']('+git_url+')\n\n> Enlace tomado de `despliegue.md`. Verificar acceso y confirmar que esta versión de Semana 9 fue publicada.',
 'README: enlace GitHub')
read=read.replace('`bancoxyz_batch_eft_aislado`','`bancoxyz`')
put('README.md',read)

ins=section(ins,'## 2. Prueba integral','## 3. Ejecución manual',
 '''
La validación utilizada en Semana 9 es el auditor de cierre, ya instalado en `Semana 9/scripts/`:

```fish
bash 'Semana 9/scripts/cierre_total_bancoxyz_s9.sh' --todo
```

Orden de comprobación: CSV oficiales (3 × 1.000 registros), estructura, Maven, Compose, PostgreSQL, ejecución real de los tres Jobs, idempotencia por tabla y SHA-256 de CSV. La base de datos objetivo es **`bancoxyz`** y su acceso desde el host fue validado en `127.0.0.1:5432`.

Con el stack levantado, el flag `--probar-bff` incorpora comprobaciones BFF/OAuth2. Las pruebas de Kafka que incluyen retiros o pausas del listener deben ejecutarse conscientemente, no como parte de un script que borre datos.

El informe de cierre no transforma una falta en éxito: Pagos aún no liquida operaciones y el video MP4 no se genera automáticamente.
''', 'instrucciones: prueba integral')
ins=section(ins,'## 4. Resultados esperados','NO_END_SENTINEL', '', 'N/A') if False else ins
pos=ins.find('## 4. Resultados esperados')
if pos<0 and '## 4. Resultados verificados en Semana 9 (11-10-2026)' not in ins: raise RuntimeError('Falta seccion resultados de instrucciones.md')
if pos>=0:
 ins=ins[:pos]+'''## 4. Resultados verificados en Semana 9 (11-10-2026)

- Maven: **BUILD SUCCESS**, sin fallos ni errores informados.
- Compose: configuración válida; un servicio PostgreSQL; única base de usuario detectada: **`bancoxyz`**.
- Batch: `transaccionJob` (31), `cuentaInteresJob` (32) y `estadoCuentaAnualJob` (33) finalizados con estado **COMPLETED** persistido.
- Tablas: 474 transacciones, 50 cuentas con intereses, 20 estados anuales y 261 resúmenes diarios.
- Segunda ejecución: se conservan conteos y contenido de negocio de las cuatro tablas derivadas.
- Integridad: los tres CSV oficiales de Semana 9 conservan el mismo SHA-256.
- Seguridad/Kafka: comprobaciones funcionales anteriores de 200/401/403 y pause/resume del listener; consultar evidencias originales.

Pendiente para certificación completa: liquidación de pagos/transferencias/depósitos, evidencias EC2/TLS/escala real, informe contrastado con la plantilla AVA y video MP4 con webcam.
'''
put('instrucciones.md',ins)

des=replace_exact(des,"fish 'Semana 9/scripts/verificar_entrega_completa.fish' --ec2",
 "bash 'Semana 9/scripts/cierre_total_bancoxyz_s9.sh' --todo --probar-bff",
 'despliegue: verificación EC2')
des=replace_exact(des,
 'Este es el script único de aceptación. Verifica CSV, Maven, Compose, Jobs Batch, OAuth2, BFF, Kafka, listener, Resilience4j, retiro controlado y el issuer público de Keycloak con TLS válido.',
 'Este es el script de auditoría local de código, CSV, Maven, Compose y Jobs Batch sobre `bancoxyz`; con `--probar-bff` agrega pruebas de canal cuando el stack está levantado. TLS público, issuer HTTPS y Kafka end-to-end requieren comprobaciones externas adicionales en la EC2 y las evidencias correspondientes. El auditor NO despliega ni certifica automáticamente la nube.',
 'despliegue: alcance auditor')
put('despliegue.md',des)

pro=replace_exact(pro, 'ejecuta Batch de forma aislada.',
 'consolida Batch y los tres servicios de dominio en PostgreSQL `bancoxyz`.',
 'propuesta: descripción arquitectura')
pro=pro.replace('    BATCHDB["PostgreSQL Batch aislado"]', '    BATCHDB["PostgreSQL 17: bancoxyz"]')
pro=replace_exact(pro,'    BATCH --> BATCHDB',
 '    BATCH --> DB','propuesta: diagrama enlace')
pro=pro.replace('    BATCHDB["PostgreSQL 17: bancoxyz"]\n','')
if '### 8.1 Resultados reales de reejecución' not in pro:
 marker='## 9. Trazabilidad con la pauta de evaluación'
 if marker not in pro: raise RuntimeError('Propuesta Técnica sin apartado 9')
 pro=pro.replace(marker,'''### 8.1 Resultados reales de reejecución

En la validación del 11 de octubre de 2026, los tres CSV oficiales tenían 1.000 registros cada uno. Los Jobs `transaccionJob` (31), `cuentaInteresJob` (32) y `estadoCuentaAnualJob` (33) terminaron **COMPLETED** y mantuvieron, después de reejecución, **474** transacciones procesadas, **50** cuentas con intereses, **20** estados anuales y **261** resúmenes diarios, sin cambios de negocio en dichas tablas. Los CSV permanecieron intactos.

La pauta requiere procesamiento de pagos, transferencias y depósitos: la versión auditada de `pagos-service` todavía solo registra solicitudes `PENDIENTE`. No se considera liquidación monetaria real hasta implementar y probar la afectación transaccional de cuentas.

'''+marker)
put('Propuesta_Tecnica.md',pro)

# Guion reproducible, pero NO equivale al MP4 solicitado.
video='''# Guion de video BancoXYZ EFT Semana 9 · 5-7 minutos

**0:00-0:40 — Presentación y resumen ejecutivo (webcam).** Contexto legacy, cinco procesos de modernización y arquitectura con Spring Batch, BFF, microservicios, JWT, Kafka y Docker.

**0:40-2:05 — Arquitectura y datos.** Abrir `Propuesta_Tecnica.md` y el diagrama. Enseñar tres CSV de `Semana 9/batch-service/src/main/resources/data/`, 1000 registros cada uno. Mostrar PostgreSQL unificado `bancoxyz` y tres Jobs Batch.

**2:05-3:20 — Resultados obtenidos.** Enseñar salida de `cierre_total_bancoxyz_s9.sh`: Maven BUILD SUCCESS, JobExecution 31/32/33 COMPLETED, 474/50/20/261 filas e idempotencia preservada. Mostrar que los tres CSV no se modifican.

**3:20-4:25 — Seguridad y servicios.** Mostrar BFF Web/Mobile/ATM, scopes OAuth2, Keycloak, Resilience4j, Eureka y los tres microservicios de dominio. Explicar con transparencia que `pagos-service` todavía recibe solicitudes PENDIENTE y no liquida dinero.

**4:25-5:30 — Comparación legacy y desafíos.** Antes: jobs monolíticos, menor separación. Ahora: Jobs auditables, microservicios escalables y mensajería Kafka. Desafíos: puertos PostgreSQL, idempotencia y event afterCommit.

**5:30-6:20 — Mejoras propuestas y cierre.** Procesamiento transaccional real de pagos, entrega fiable Kafka, evidencia de despliegue EC2/TLS y escalamiento. Cerrar con resumen de resultados.

Grabar webcam visible, exportar MP4 y verificar duración 5-7 min. Este archivo es solo guion; NO reemplaza el video.
'''
changes['Guion_Video_EFT_S9.md']=video

pdf_data=gzip.decompress(base64.b64decode(''''''))
pdf_path=root/'Informe_Tecnico_BancoXYZ_S9.pdf'
# No sobrescribir un informe existente distinto.
if pdf_path.exists() and pdf_path.read_bytes()!=pdf_data:
    raise RuntimeError('Ya existe Informe_Tecnico_BancoXYZ_S9.pdf distinto: no se reemplazó. Moverlo manualmente si se desea instalar este informe.')
# Validar todas las rutas antes de escribir archivos.
for name in changes:
 f=root/name
 if f.exists() and not f.is_file(): raise RuntimeError('Ruta no es archivo: '+name)
# Escritura idempotente: solo .md de raiz, sin backups ni archivos basura.
for name,data in changes.items():
 path=root/name
 raw=data.encode('utf-8')
 if path.exists() and path.read_bytes()==raw:
  print('SIN CAMBIOS:', name);continue
 temp=path.with_name('.'+path.name+'.s9tmp')
 try:
  temp.write_bytes(raw)
  os.replace(temp,path)
 finally:
  if temp.exists():temp.unlink()
 print('ACTUALIZADO:',name)
if not pdf_path.exists():
 pdf_path.write_bytes(pdf_data)
 print('CREADO: Informe_Tecnico_BancoXYZ_S9.pdf (informe técnico; contrastar con plantilla AVA)')
else:print('SIN CAMBIOS: Informe_Tecnico_BancoXYZ_S9.pdf')
print('OK: documentacion y PDF preparados. Datos y codigo no modificados.')
print('PENDIENTES REALES: pagos monetarios, MP4 webcam, contraste plantilla AVA y evidencia cloud.')
PYTHON_S9
# Diagnóstico final SIN reejecutar Jobs ni compilar, para no recrear target/.
if [[ -f "$ROOT/Semana 9/scripts/cierre_total_bancoxyz_s9.sh" ]]; then
 echo '==== AUDITORIA ESTATICA POSTERIOR (NO reejecuta Batch) ===='
 set +e
 ( cd "$ROOT" && bash 'Semana 9/scripts/cierre_total_bancoxyz_s9.sh' --estatico )
 rc=$?
 set -e
 echo "AUDITORIA ESTATICA EXIT=$rc (puede seguir != 0 por pagos/video/evidencias pendientes)."
fi
exit 0
